<script setup lang="ts">
import {ref,computed,onMounted,watch,onBeforeUnmount} from 'vue';
import {campaignApi} from '../campaign-api';import type {WorkTab} from '../stores';import Modal from './Modal.vue';import {eventOverwrite,describeEvent,groupEventsByMonth,weekdayLabel,overlappingDays,WEEKDAY_NAMES,EVENT_TYPE_LABEL} from '../../../lib/workspace/campaign-rules';
const props=defineProps<{mode:'settings'|'events';tab:WorkTab;canEdit:boolean}>();
const loading=ref(false),error=ref(''),message=ref(''),stores=ref<any[]>([]),rows=ref<any[]>([]),selected=ref(''),pendingStore=ref<string|null>(null),deleting=ref<any>(null),overwrite=ref<any>(null);
const form=ref<any>({allowed_days:[],forbidden_days:[],notes:'',event_date:'',description:'',event_type:'holiday',is_blocked:false}),baseline=ref(JSON.stringify(form.value));
const dirty=computed(()=>JSON.stringify(form.value)!==baseline.value);watch(dirty,v=>props.tab.dirty=v,{flush:'sync'});props.tab.submitOnly=true;
const days=['週一','週二','週三','週四','週五','週六','週日'];
async function load(){loading.value=true;error.value='';try{const r=await campaignApi(props.mode);rows.value=r.settings||r.events||[];if(props.mode==='settings'){const s=await campaignApi('stores');stores.value=s.stores||s.data||[];}}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function choose(id:string){selected.value=id;const r=rows.value.find(x=>x.store_id===id);form.value={allowed_days:r?.allowed_days||[],forbidden_days:r?.forbidden_days||[],notes:r?.notes||''};baseline.value=JSON.stringify(form.value);}
function switchStore(e:Event){const input=e.target as HTMLSelectElement,id=input.value;if(dirty.value){input.value=selected.value;pendingStore.value=id;}else choose(id);}
const grouped=computed(()=>groupEventsByMonth(props.mode==='events'?rows.value:[]));
async function save(confirmed=false){if(props.mode==='events'&&!confirmed){const old=eventOverwrite(rows.value,form.value);if(old){overwrite.value=old;return;}}overwrite.value=null;props.tab.busy=true;error.value='';message.value='';try{if(props.mode==='settings'&&!selected.value)throw Error('請選擇門市');{const both=overlappingDays(form.value.allowed_days,form.value.forbidden_days);if(props.mode==='settings'&&both.length)throw Error('週'+both.map((d:number)=>WEEKDAY_NAMES[d]).join('、')+'同時設為可安排與禁止安排，這樣永遠排不進去，請擇一');}await campaignApi(props.mode,{},'POST',{...form.value,...(props.mode==='settings'?{store_id:selected.value}:{})});baseline.value=JSON.stringify(form.value);props.tab.dirty=false;message.value='已儲存';await load();}catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
async function remove(){props.tab.busy=true;error.value='';try{await campaignApi('events',{id:deleting.value.id},'DELETE');deleting.value=null;await load();message.value='已刪除特殊日期';}catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
onMounted(load);onBeforeUnmount(()=>{props.tab.dirty=false;delete props.tab.submitOnly;});
</script>
<template><p v-if="error" role="alert" class="notice error">{{error}} <button :disabled="tab.busy" @click="load">重新讀取</button></p><p v-if="message" role="status" class="notice">{{message}}</p><p v-if="loading">正在讀取設定…</p>
<template v-else><form @submit.prevent="save()"><fieldset :disabled="tab.busy || (mode==='events' && !canEdit)"><template v-if="mode==='settings'"><label>門市<select aria-label="門市" :value="selected" @change="switchStore"><option value="">請選擇</option><option v-for="s in stores" :value="s.id">{{s.store_code}} {{s.store_name}}</option></select></label><template v-if="selected"><h3>可安排星期</h3><p>未勾選代表不另外限制星期。</p><div class="days"><label v-for="(day,i) in days"><input type="checkbox" :disabled="!canEdit" :value="i+1" v-model="form.allowed_days">{{day}}</label></div><h3>禁止安排星期</h3><div class="days"><label v-for="(day,i) in days"><input type="checkbox" :disabled="!canEdit" :value="i+1" v-model="form.forbidden_days">{{day}}</label></div><label>備註<textarea :disabled="!canEdit" v-model="form.notes" rows="3"/></label></template></template>
<template v-else><h3>新增特殊日期</h3><div class="fields"><label>日期<input type="date" v-model="form.event_date" required></label><label>類型<select v-model="form.event_type"><option value="holiday">國定假日</option><option value="company_event">公司活動</option><option value="other">其他</option></select></label><label>說明<input v-model="form.description" maxlength="1000"></label><label class="check"><input type="checkbox" v-model="form.is_blocked">禁止自動排程</label></div></template>
<div class="dialog-actions"><button v-if="canEdit" class="primary" :disabled="!dirty||tab.busy||mode==='settings'&&!selected">{{tab.busy?'儲存中…':mode==='events'?'新增日期':'儲存門市設定'}}</button></div></fieldset></form>
<div v-if="mode==='events'" class="module-table"><template v-for="g in grouped" :key="g.month"><h3 class="month">{{g.month}}（{{g.rows.length}} 筆）</h3><table><thead><tr><th>日期</th><th>星期</th><th>類型</th><th>說明</th><th>限制</th><th>操作</th></tr></thead><tbody><tr v-for="r in g.rows" :key="r.id"><td>{{r.event_date.slice(0,10)}}</td><td>{{weekdayLabel(r.event_date)}}</td><td>{{EVENT_TYPE_LABEL[r.event_type]||'其他'}}</td><td>{{r.description}}</td><td>{{r.is_blocked?'禁止自動排程':'允許排程'}}</td><td><button v-if="canEdit" :disabled="tab.busy" @click="deleting=r">刪除</button></td></tr></tbody></table></template><p v-if="!rows.length">尚無特殊日期。</p></div></template>
<Modal v-if="pendingStore!==null" title="切換門市？" @cancel="pendingStore=null"><p>此門市尚未儲存的設定將被放棄。</p><div class="dialog-actions"><button @click="pendingStore=null">繼續編輯</button><button class="danger" @click="choose(pendingStore!);pendingStore=null">放棄並切換</button></div></Modal>
<Modal v-if="overwrite" title="這一天已有特殊日期" @cancel="overwrite=null"><p>原本的內容：</p><p class="was">{{describeEvent(overwrite)}}</p><p>儲存後會改成：</p><p class="was">{{describeEvent(form)}}</p><p>覆蓋後，自動排程的結果可能跟著改變（例如禁止日變成可排程）。要覆蓋嗎？</p><div class="dialog-actions"><button @click="overwrite=null">取消</button><button class="danger" @click="save(true)">確認覆蓋</button></div></Modal>
<Modal v-if="deleting" title="刪除特殊日期？" :busy="tab.busy" @cancel="deleting=null"><p>{{deleting.event_date}} {{deleting.description}}，刪除後不再提供此日期限制。</p><div class="dialog-actions"><button :disabled="tab.busy" @click="deleting=null">取消</button><button class="danger" :disabled="tab.busy" @click="remove">確認刪除</button></div></Modal>
</template>
<style scoped>.month{margin:20px 0 8px}.was{padding:8px 10px;background:var(--bg);border-left:3px solid var(--primary)}fieldset{padding:0;border:0;min-width:0}label{display:grid;gap:8px;margin:12px 0}.days{display:flex;gap:14px;flex-wrap:wrap}.days label,.check{display:flex;align-items:center;gap:8px}.days input,.check input{width:18px;min-height:18px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}h3{font-size:16px;margin-top:24px}input,select,textarea{max-width:100%}@media(max-width:600px){.fields{grid-template-columns:1fr}}</style>
